	@Test
	void typedSelectionNeverBorrowsRhsOnlyOrEncodedChildBindings(@TempDir Path directory) {
		try (NativeFixture fixture = new NativeFixture(directory)) {
			SelectionInput input = selection(true, 1);
			fixture.withSession(input.expression(), nativeSession -> {
				SelectionState selected = priceSelection(nativeSession, input, 2);
				assertFalse(nativeSession.call.query()
						.relationAssuresBinding(
								selected.actualPrefixRelation(), "person"),
						"person belongs to the omitted encoded child, not the supplied actual left");
				// The Person factor is present in the encoded child but is not bound by the actual relocated input.
				PackedCostEstimate person = nativeSession.leaf(nativeSession.call.rightRelationId());
				double isolatedRows = person.outputRows();
				nativeSession.session.appendFactor(nativeSession.call.rightRelationId(), restricted(selected), person);
				assertEquals(isolatedRows, person.outputRows(), 0.0d);
				assertFalse(person.hasContextualOutputRows(),
						"encoded-child-only person cannot authorize a bound probe");
				assertFalse((person.lookupComponentMask() & 1) != 0,
						"neither an encoded child nor an RHS-only binding may supply the missing subject");
				assertFalse(nativeSession.call.query()
						.relationAssuresBinding(
								selected.actualPrefixRelation(), "rhsOnly"));
				int rhsOnlyRelation = 0;
				for (int relation = 1; relation <= nativeSession.call.query().relationCount(); relation++) {
					if (nativeSession.call.query().isStatementPattern(relation)
							&& "rhsOnly".equals(nativeSession.call.query().statementPatternName(relation, 0))) {
						rhsOnlyRelation = relation;
					}
				}
				assertTrue(rhsOnlyRelation > 0, "the captured RHS really contains the exclusive binding");
				PackedCostEstimate rhsOnly = nativeSession.leaf(rhsOnlyRelation);
				double isolatedRhsRows = rhsOnly.outputRows();
				nativeSession.session.appendFactor(rhsOnlyRelation, restricted(selected), rhsOnly);
				assertEquals(isolatedRhsRows, rhsOnly.outputRows(), 0.0d);
				assertFalse(rhsOnly.hasContextualOutputRows(), "RHS-only outputs cannot become actual-left inputs");
				assertEquals(0, rhsOnly.lookupComponentMask() & 5, "RHS subject/object bindings remain unavailable");
				return null;
			});
		}
	}

