	private static Stream<Arguments> selectionVariants() {
		Stream.Builder<Arguments> variants = Stream.builder();
		for (boolean anti : new boolean[] { false, true }) {
			for (int algorithm : new int[] { 0, 1, 2 }) {
				for (int depth : new int[] { 1, 3 }) {
					variants.add(Arguments.of(anti, algorithm, depth));
				}
			}
		}
		return variants.build();
	}

	private static SelectionInput selection(boolean anti, int aliasDepth) {
		List<BindingSet> organizations = new ArrayList<>();
		List<BindingSet> events = new ArrayList<>();
		for (int branch = 0; branch < 4; branch++) {
			organizations.add(new ListBindingSet(List.of("org"), end(branch)));
			events.add(new ListBindingSet(List.of("event"), VF.createIRI("urn:qualified-row:event:" + branch)));
		}
		TupleExpr alias = assignment(List.of("event"), events);
		String source = "event";
		for (int depth = 1; depth <= aliasDepth; depth++) {
			String target = depth == aliasDepth ? "fanout" : "eventAlias" + depth;
			alias = new Extension(alias, new ExtensionElem(Var.of(source), target));
			source = target;
		}
		Join actualPrefix = new Join(assignment(List.of("org"), organizations), alias);
		Join originalLeft = new Join(actualPrefix, pattern("person", MEMBER, "org"));
		TupleExpr rhs = new Join(new Join(pattern("org", EMPLOYEE, "fanout"),
				pattern("fanout", RDF.TYPE, "rhsOnly")), pattern("rhsOnly", STEP, "rightTail"));
		ValueExpr predicate = new Exists(rhs);
		if (anti) {
			predicate = new Not(predicate);
		}
		Filter originalSelection = new Filter(originalLeft, predicate);
		Join expression = new Join(originalSelection,
				new StatementPattern(Var.of("person"), Var.of("type", RDF.TYPE),
						Var.of("personClass", PERSON)));
		return new SelectionInput(expression, predicate, anti);
	}

	private static SelectionState priceSelection(NativeSession nativeSession, SelectionInput input, int algorithm) {
		PackedQueryView query = nativeSession.call.query();
		int ordinarySelection = nativeSession.call.leftRelationId();
		int memberJoin = query.childRelationId(ordinarySelection, 0);
		int actualPrefix = query.childRelationId(memberJoin, 0);
		int member = query.childRelationId(memberJoin, 1);
		int alias = query.childRelationId(actualPrefix, 1);
		assertTrue(query.hasOnlyPureBindingAliasWrites(alias),
				"the actual origin contains a captured sequential fresh WHOLE alias");
		assertTrue(query.hasOrdinaryBindingWrites(alias), "the BAG really contains a writing operand");
		PackedCostEstimate left = nativeSession.pricePrefix(actualPrefix);
		assertTrue(left.evidenceStateId() > 0);
		List<Integer> typed = new ArrayList<>();
		for (int relation = 1; relation <= query.relationCount(); relation++) {
			if (input.anti() ? query.isAntiJoin(relation) : query.isSemiJoin(relation)) {
				typed.add(relation);
			}
		}
		typed.sort(Comparator.comparingInt(query::semiAntiAlgorithm));
		assertEquals(3, typed.size(), "the real encoder must expose all three typed selection alternatives");
		int relation = typed.get(algorithm);
		assertNotEquals(actualPrefix, query.childRelationId(relation, 0),
				"the supplied actual-left bag omits memberOf, unlike the encoded child population");
		TupleExpr actualSelection = new Filter(query.materializeRelation(actualPrefix).clone(),
				input.predicate().clone());
		double actualRows = nativeSession.count(actualSelection);
		PackedCostEstimate output = new PackedCostEstimate();
		output.setContextualRows(actualRows, left.workRows() + actualRows);
		var context = nativeSession.call.operatorContext(left.outputRows(), Double.NaN, left.evidenceStateId(), 0);
		nativeSession.session.refineOperator(relation, context, output);
		return new SelectionState(output, actualPrefix, member, memberJoin, ordinarySelection);
	}

	private static PackedCostEstimate continuation(NativeSession nativeSession, SelectionInput input, int algorithm,
			boolean checkEveryStep) {
		SelectionState selected = priceSelection(nativeSession, input, algorithm);
		PackedCostEstimate isolatedMember = nativeSession.leaf(selected.memberRelation());
		PackedCostEstimate member = append(nativeSession, selected.memberRelation(), selected.output(),
				selected.actualPrefixRelation(), Set.of("org"), checkEveryStep);
		PackedCostEstimate joined = join(nativeSession, selected.memberJoinRelation(), selected.output(),
				isolatedMember, member, selected.actualPrefixRelation(), checkEveryStep);
		// A repeated ordinary selection is an idempotent nested-selection variant and gives every captured
		// source operator a genuine callback event for recipe extraction; no private state is manufactured.
		PackedCostEstimate nested = copy(joined);
		nativeSession.session.refineOperator(selected.ordinarySelectionRelation(),
				nativeSession.call.operatorContext(joined.outputRows(), Double.NaN, joined.evidenceStateId(), 0),
				nested);
		nativeSession.remember(selected.ordinarySelectionRelation(), nested);
		int person = nativeSession.call.rightRelationId();
		PackedCostEstimate isolatedPerson = nativeSession.leaf(person);
		PackedCostEstimate appendedPerson = append(nativeSession, person, nested,
				selected.ordinarySelectionRelation(), Set.of("person"), checkEveryStep);
		return join(nativeSession, nativeSession.call.operatorRelationId(), nested, isolatedPerson, appendedPerson,
				selected.ordinarySelectionRelation(), checkEveryStep);
	}

	private static PackedCostEstimate append(NativeSession nativeSession, int relation, PackedCostEstimate prefix,
			int listedPrefix, Set<String> actualNames, boolean check) {
		PackedCostEstimate output = nativeSession.leaf(relation);
		var producer = nativeSession.producer(nativeSession.call.query().materializeRelation(relation), actualNames,
				prefix.outputRows(), 1.0d);
		var context = PackedCostTestSupport.restrictedPrefixContext(new int[] { listedPrefix }, 1,
				prefix.outputRows(), prefix.evidenceStateId());
		nativeSession.session.appendFactor(relation, context, output);
		if (check) {
			assertNativeRows(producer, output, "typed selection continuation, relation=" + relation);
			assertBindingOnly(output);
		}
		return nativeSession.remember(relation, output);
	}

	private static PackedCostEstimate join(NativeSession nativeSession, int relation, PackedCostEstimate left,
			PackedCostEstimate isolatedRight, PackedCostEstimate appended, int listedPrefix, boolean check) {
		PackedCostEstimate output = copy(appended);
		var context = PackedCostTestSupport.restrictedPrefixContext(new int[] { listedPrefix }, 1,
				left.outputRows(), appended.evidenceStateId());
		PackedCostTestSupport.operatorInputs(context, left.outputRows(), isolatedRight.outputRows(),
				left.evidenceStateId(), isolatedRight.evidenceStateId());
		nativeSession.session.refineOperator(relation, context, output);
		nativeSession.session.refineIntermediateJoin(context, output);
		PackedCostTestSupport.refineDependentPhysicalJoin(nativeSession.session, context, output);
		if (check) {
			assertBindingOnly(output);
		}
		return nativeSession.remember(relation, output);
	}

	private static PackedCostContext restricted(SelectionState selected) {
		return PackedCostTestSupport.restrictedPrefixContext(new int[] { selected.actualPrefixRelation() }, 1,
				selected.output().outputRows(), selected.output().evidenceStateId());
	}

	private static PackedCostEstimate copy(PackedCostEstimate source) {
		PackedCostEstimate target = new PackedCostEstimate();
		PackedCostTestSupport.copyCandidate(source, target);
		return target;
	}

	private record SelectionInput(Join expression, ValueExpr predicate, boolean anti) {
	}

	private record SelectionState(PackedCostEstimate output, int actualPrefixRelation, int memberRelation,
			int memberJoinRelation, int ordinarySelectionRelation) {
	}
